#!/bin/bash
# ============================================================================
# Fase 8L -- TMS BigMat
#
# Rediseno UI/UX de la App Conductor (ficha de parada) segun la
# especificacion de Raul:
#   - Cabecera fija en color corporativo con boton de retroceso e ID de
#     pedido real, e isotipo.
#   - Mapa "sticky" del destino en la parte alta de la pantalla.
#   - Tarjeta principal: chip de estado, direccion grande, boton "Como
#     llegar" (navegacion GPS real).
#   - Tarjetas secundarias: ventana horaria, ETA, contacto (llamada +
#     WhatsApp de un toque), notas del conductor (editables y persistidas).
#   - Barra de acciones inferior con los 5 iconos (Foto / Notas / Firma /
#     Formularios / Escaner de codigos), cada uno con indicador verde/rojo
#     de completado -- "Formularios" reutiliza el formulario de
#     incidencia/retorno ya existente; "Escaner" es nuevo de verdad (abre
#     camara y registra el codigo contra la parada).
#   - CTA final "Completar entrega" mas grande, y tipografia/espaciado
#     pensados para leerse al sol.
#   - Tras completar una parada, ahora si se vuelven a mostrar la firma y
#     las fotos ya capturadas (antes desaparecian).
#
# Ademas, rediseno del Portal de Consulta al Cliente (/seguimiento) como app
# de seguimiento en vez de formulario web centrado: cabecera fija
# corporativa, tarjetas a todo el ancho, tipografia mas grande, y
# auto-actualizacion cada 20s mientras el pedido esta "en reparto".
#
# Cambios de base de datos (aditivos, sin tocar nada existente):
#   RouteStop.driverNotes    String? -- nota libre del conductor por parada
#   RouteStop.scannedCodes   Json?   -- codigos escaneados (palet/bulto)
#
# Aplica este script desde la raiz del repo (tms-production).
#
# Tras aplicarlo:
#   cd backend && npx prisma generate && npx prisma db push
#   cd apps/driver-app && npm install   # nuevas deps: leaflet, react-leaflet, @types/leaflet
# ============================================================================
set -euo pipefail

if [ ! -d "backend" ] || [ ! -d "apps/driver-app" ] || [ ! -d "apps/customer-portal" ]; then
  echo "ERROR: ejecuta este script desde la raiz del repo tms-production (deben existir backend/, apps/driver-app/ y apps/customer-portal/)."
  exit 1
fi

echo "Aplicando Fase 8L..."

echo "  -> backend/prisma/schema.prisma"
mkdir -p "backend/prisma"
base64 -d > "backend/prisma/schema.prisma" <<'B64EOF_0'
